// SPDX-License-Identifier: AGPL-3.0-only
// Generates src/generated.ts from openapi.json (itself generated by the control plane). Covers
// the subset of OpenAPI 3.1 the control plane emits; anything else fails loudly.
import { readFileSync, writeFileSync } from "node:fs";

type Schema = {
  type?: string | string[];
  $ref?: string;
  enum?: string[];
  oneOf?: Schema[];
  items?: Schema;
  properties?: Record<string, Schema>;
  required?: string[];
  description?: string;
};
type Parameter = { name: string; in: string };
type Operation = {
  operationId: string;
  description?: string;
  summary?: string;
  security?: unknown[];
  parameters?: Parameter[];
  requestBody?: { content: { "application/json": { schema: Schema } } };
  responses: Record<string, { content?: Record<string, { schema: Schema } | undefined> }>;
};
type Doc = { info: { version: string }; paths: Record<string, Partial<Record<Method, Operation>>>; components: { schemas: Record<string, Schema> } };
const METHODS = ["get", "post", "put", "patch", "delete"] as const;
type Method = (typeof METHODS)[number];

/** Media types the client returns as text rather than parsing JSON. */
const isText = (type: string) => type.startsWith("text/") || type === "application/x-ndjson";
/** Files to save (the support bundle): the client returns them as a `Blob`. */
const isBinary = (type: string) => ["application/x-tar", "application/zip", "application/octet-stream"].includes(type);

const doc = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url), "utf8")) as Doc;

const comment = (text: string | undefined, indent = "") =>
  text ? `${indent}/** ${text.trim().replace(/\*\//g, "*\\/").replace(/\n+/g, ` `)} */\n` : "";

function ts(s: Schema, indent: string): string {
  if (s.$ref) return s.$ref.replace("#/components/schemas/", "");
  if (s.enum) return s.enum.map((v) => JSON.stringify(v)).join(" | ");
  if (s.oneOf) return s.oneOf.map((x) => ts(x, indent)).join(" | ");
  const types = Array.isArray(s.type) ? s.type : s.type ? [s.type] : [];
  const nonNull = types.filter((t) => t !== "null");
  const nullable = types.includes("null") ? " | null" : "";
  if (nonNull.length > 1) throw new Error(`unsupported union ${JSON.stringify(s)}`);
  switch (nonNull[0]) {
    case "string": return `string${nullable}`;
    case "boolean": return `boolean${nullable}`;
    case "integer": case "number": return `number${nullable}`;
    case "array": return `${wrap(ts(s.items ?? {}, indent))}[]${nullable}`;
    case "object": {
      if (!s.properties) return `Record<string, unknown>${nullable}`;
      const req = new Set(s.required ?? []);
      const inner = indent + "  ";
      const fields = Object.entries(s.properties).map(([k, v]) => `${comment(v.description, inner)}${inner}${k}${req.has(k) ? "" : "?"}: ${ts(v, inner)};`);
      return `{\n${fields.join("\n")}\n${indent}}${nullable}`;
    }
    // `{"type": "null"}` (an optional reference is `oneOf: [null, $ref]`).
    case undefined: return types.includes("null") ? "null" : "unknown";
    default: throw new Error(`unsupported type ${JSON.stringify(s)}`);
  }
}
const wrap = (t: string) => (t.includes("|") ? `(${t})` : t);

const out: string[] = [
  "// SPDX-License-Identifier: AGPL-3.0-only",
  "// GENERATED by scripts/generate.ts from openapi.json. Do not edit; run `npm run api:generate`.",
  "",
  `export const API_VERSION = ${JSON.stringify(doc.info.version)};`,
  "",
];
for (const [name, s] of Object.entries(doc.components.schemas)) {
  out.push(`${comment(s.description)}export type ${name} = ${ts(s, "")};`, "");
}

const ops = Object.entries(doc.paths).flatMap(([path, item]) =>
  METHODS.flatMap((method) => (item[method] ? [{ path, method, op: item[method]! }] : [])),
);
const isPublic = (op: Operation) => op.security?.length === 1 && JSON.stringify(op.security[0]) === "{}";
const pathParams = (op: Operation) => (op.parameters ?? []).filter((p) => p.in === "path").map((p) => p.name);

out.push("/** Operations by operationId: method, path template, path parameters and whether a token is needed. */");
out.push("export const operations = {");
for (const { path, method, op } of ops) {
  out.push(`  ${op.operationId}: { method: ${JSON.stringify(method.toUpperCase())}, path: ${JSON.stringify(path)}, params: ${JSON.stringify(pathParams(op))}, public: ${isPublic(op)} },`);
}
out.push("} as const;", "");

out.push("/** Success body of each operation (`null` for 204 No Content). */");
out.push("export type Responses = {");
for (const { op } of ops) {
  const code = Object.keys(op.responses).find((c) => c.startsWith("2"));
  const ok = code && op.responses[code]?.content?.["application/json"]?.schema;
  // A text answer (the metrics exposition, the audit export as CSV or JSON lines) is a string.
  const text = code && Object.keys(op.responses[code]?.content ?? {}).some(isText);
  const binary = code && Object.keys(op.responses[code]?.content ?? {}).some(isBinary);
  if (!ok && !text && !binary && code !== "204") throw new Error(`${op.operationId}: no 2xx JSON, text or file response`);
  out.push(`${comment(op.description ?? op.summary, "  ")}  ${op.operationId}: ${ok ? ts(ok, "  ") : text ? "string" : binary ? "Blob" : "null"};`);
}
out.push("};", "");

out.push("/** Request body of each operation (`never` when it takes none). */");
out.push("export type Bodies = {");
for (const { op } of ops) {
  const body = op.requestBody?.content["application/json"].schema;
  out.push(`  ${op.operationId}: ${body ? ts(body, "  ") : "never"};`);
}
out.push("};", "");

writeFileSync(new URL("../src/generated.ts", import.meta.url), out.join("\n"));
console.log(`api client generated: ${Object.keys(doc.components.schemas).length} types, ${ops.length} operations`);
